// src/App.js
import React, { useState } from "react";
import { Routes, Route, Navigate, useNavigate } from "react-router-dom";

import Navbar from "./components/Navbar";
import Sidebar from "./components/Sidebar";
import Footer from "./components/Footer";
import SciPetChat from "./components/SciPetChat";

// Pages
import Home from "./pages/Home";
import About from "./pages/About";
import Mission from "./pages/Mission";
import Features from "./pages/Features";
import Login from "./pages/Login";
import Signup from "./pages/Signup";
import Dashboard from "./pages/Dashboard";
import Resources from "./pages/Resources"; 
import SubscienceUnit from "./pages/SubscienceUnit";
import ScienceDetail from "./pages/ScienceDetail";
import Worksheet from "./pages/Worksheet";
import WorksheetAnalysis from "./pages/WorksheetAnalysis";
import Schedule from "./pages/Schedule";
import Games from "./pages/Games";          // keep your existing
import PublicChat from "./pages/PublicChat"; // existing generic chat
import Profile from "./pages/Profile";
import AboutTutors from "./pages/AboutTutors";
import AIQuiz from "./pages/AIQuiz";

useEffect(() => {
  const saved = localStorage.getItem("user");
  if (saved) {
    setUser(JSON.parse(saved));
  }
}, []);

function App() {
  const [user, setUser] = useState(null);
  const [worksheetResult, setWorksheetResult] = useState(null);
  const [theme, setTheme] = useState("dark");
  const [notifications, setNotifications] = useState([]);

  // New dashboard-related state
  const [stats, setStats] = useState({
    xp: 0,
    coins: 0,
    streak: 0,
    lessonsCompleted: 0,
    lessonsInProgress: 0,
    totalGameScore: 0,
  });

  const [recentActivity, setRecentActivity] = useState([]);
  const [bookedSessions, setBookedSessions] = useState([]);

  const navigate = useNavigate();

  function toggleTheme() {
    setTheme((prev) => (prev === "dark" ? "light" : "dark"));
  }

  function addNotification(text) {
    const id = Date.now();
    setNotifications((prev) => [...prev, { id, text }]);
    setTimeout(() => {
      setNotifications((prev) => prev.filter((n) => n.id !== id));
    }, 4000);
  }

  function handleLogin(userData) {
    setUser(userData);
    localStorage.setItem("user", JSON.stringify(userData));
    addNotification("Logged in successfully");
    navigate("/dashboard");
}


  function handleSignup(userData) {
    setUser(userData);
    localStorage.setItem("user", JSON.stringify(userData));
    addNotification("Account created successfully");
    navigate("/dashboard");
}


  function handleLogout() {
    setUser(null);
    setStats({
    xp: 0,
    coins: 0,
    streak: 0,
    lessonsCompleted: 0,
    lessonsInProgress: 0,
    totalGameScore: 0,
  });
  setRecentActivity(null)
    addNotification("Logged out");
    navigate("/");
  }

  // Dashboard helpers
  function addActivity(activity) {
    setRecentActivity((prev) => [
      { id: Date.now(), ...activity },
      ...prev,
    ]);
  }

  function addBookedSession(session) {
    setBookedSessions((prev) => [...prev, { id: Date.now(), ...session }]);
    addNotification("Session booked and saved on your dashboard");
    addActivity({
      title: `Booked session with ${session.tutorName}`,
      type: "Tutoring",
      subject: session.subject,
      status: "Upcoming",
      date: new Date().toLocaleDateString(),
    });
  }

  function handleLessonCompleted({ subject, title }) {
    setStats((prev) => ({
      ...prev,
      xp: prev.xp + 50,
      coins: prev.coins + 5,
      lessonsCompleted: prev.lessonsCompleted + 1,
    }));
    addActivity({
      title: `Completed: ${title}`,
      type: "Lesson",
      subject,
      status: "Completed",
      date: new Date().toLocaleDateString(),
    });
  }

  function handleGoToResources() {
    navigate("/resources");
  }

  function ProtectedRoute({ children }) {
    if (!user) return <Navigate to="/login" replace />;
    return children;
  }

  return (
    <div className={`app ${theme}`}>
      {/* Notifications */}
      <div className="notifications">
        {notifications.map((n) => (
          <div key={n.id} className="notification-card slide-up">
            {n.text}
          </div>
        ))}
      </div>

      {/* Public navbar only when not logged in */}
      {!user && (
        <Navbar
          user={user}
          onLogout={handleLogout}
          toggleTheme={toggleTheme}
          theme={theme}
        />
      )}

      {/* Sidebar when logged in */}
      {user && <Sidebar user={user} onLogout={handleLogout} />}

      <main
        className={`main-content ${user ? "with-sidebar" : ""}`}
        aria-live="polite"
      >
        <Routes>
          {/* Public routes */}
          {!user && (
            <>
              <Route path="/" element={<Home />} />
              <Route path="/about" element={<About />} />
              <Route path="/mission" element={<Mission />} />
              <Route path="/features" element={<Features />} />
              <Route path="/about-tutors" element={<AboutTutors />} />
              <Route path="/login" element={<Login onLogin={handleLogin} />} />
              <Route path="/signup" element={<Signup onSignup={handleSignup} />} />
            </>
          )}

          {/* Private routes */}
          {user && (
            <>
              <Route
                path="/"
                element={
                  <Dashboard
                    user={user}
                    stats={stats}
                    recentActivity={recentActivity}
                    bookedSessions={bookedSessions}
                    onGoToResources={handleGoToResources}
                  />
                }
              />
              <Route
                path="/dashboard"
                element={
                  <Dashboard
                    user={user}
                    stats={stats}
                    recentActivity={recentActivity}
                    bookedSessions={bookedSessions}
                    onGoToResources={handleGoToResources}
                  />
                }
              />

              <Route path="/resources" element={<Resources />} />
              <Route path="/subscience/:subId" element={<SubscienceUnit />} />

              <Route
                path="/resources/:branch"
                element={<Resources />}
              />
              <Route
                path="/resources/:branch/:scienceId"
                element={
                  <ScienceDetail onLessonCompleted={handleLessonCompleted} />
                }
              />

              <Route
                path="/worksheet"
                element={
                  <Worksheet onComplete={setWorksheetResult} />
                }
              />

              <Route
                path="/analysis"
                element={
                  <WorksheetAnalysis
                    result={worksheetResult}
                    onLessonFromWorksheet={handleLessonCompleted}
                  />
                }
              />

              <Route
                path="/schedule"
                element={
                  <Schedule onBookSession={addBookedSession} />
                }
              />

              <Route path="/games" element={<Games />} />
              <Route path="/games/:branch" element={<Games />} />

              <Route path="/chat" element={<PublicChat />} />
              {/* You can add /chat/:branch/:scienceId later for per-science chats */}

              <Route
                path="/profile"
                element={<Profile user={user} onUpdate={setUser} />}
              />

              <Route path="/ai-quiz" element={<AIQuiz />} />
            </>
          )}

          {/* Catch-all */}
          <Route path="*" element={<Navigate to={user ? "/dashboard" : "/"} replace />} />
        </Routes>
      </main>

      <SciPetChat />
      <Footer />
    </div>
  );
}

export default App;
